  1	package hotel.reservations;
  2	
  3	import hotel.documents.BookingReceipt;
  4	import hotel.documents.DocumentReceipt;
  5	import hotel.documents.InvoiceReceipt;
  6	import hotel.documents.ReservationReceipt;
  7	import hotel.messages.EmailSender;
  8	import hotel.rooms.Room;
  9	import hotel.rooms.Rooms;
 10	import java.math.BigDecimal;
 11	
 12	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 13	public final class ReservationService {
 14	
 15	    static final String HOTEL_NAME = "Pousada Maré Alta";
 16	
 17	    private final Rooms rooms;
 18	    private final ReservationStore store;
 19	    private final PriceCalculator priceCalculator;
 20	    private final EmailSender emailSender;
 21	
 22	    public ReservationService(
 23	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 24	        this.rooms = rooms;
 25	        this.store = store;
 26	        this.priceCalculator = priceCalculator;
 27	        this.emailSender = emailSender;
 28	    }
 29	
 30	    public synchronized Reservation create(NewReservation request) {
 31	        if (!request.checkOut().isAfter(request.checkIn())) {
 32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 33	        }
 34	        if (request.guests() < 1) {
 35	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 36	        }
 37	        Room room = rooms.find(request.roomNumber())
 38	                .orElseThrow(() -> new HotelException(
 39	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 40	        if (request.guests() > room.capacity()) {
 41	            throw new HotelException(
 42	                    ErrorCode.CAPACITY_EXCEEDED,
 43	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 44	        }
 45	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 46	            throw new HotelException(
 47	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 48	        }
 49	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
 50	        return store.add(request, price);
 51	    }
 52	
 53	    public Reservation find(long reservationId) {
 54	        return store.find(reservationId)
 55	                .orElseThrow(() -> new HotelException(
 56	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 57	    }
 58	
 59	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
 60	    public synchronized Reservation confirm(long reservationId) {
 61	        Reservation reservation = find(reservationId);
 62	        if (reservation.status() != ReservationStatus.PENDING) {
 63	            throw notAllowed(reservation, "confirm");
 64	        }
 65	        reservation.confirmPayment();
 66	        store.update(reservation);
 67	        String documentText = generateDocumentText(reservation, roomOf(reservation));
 68	        emailSender.send(
 69	                reservation.guest().email(),
 70	                "Reserva confirmada - " + HOTEL_NAME,
 71	                confirmationEmailBody(reservation, documentText));
 72	        return reservation;
 73	    }
 74	
 75	    /**
 76	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
 77	     * reservation was never paid, so nothing comes back).
 78	     */
 79	    public synchronized Reservation cancel(long reservationId) {
 80	        Reservation reservation = find(reservationId);
 81	        if (reservation.status() != ReservationStatus.PENDING
 82	                && reservation.status() != ReservationStatus.CONFIRMED) {
 83	            throw notAllowed(reservation, "cancel");
 84	        }
 85	        BigDecimal refund = switch (reservation.ratePlan()) {
 86	            case STANDARD -> reservation.amountPaid();
 87	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
 88	        };
 89	        reservation.cancel(refund);
 90	        store.update(reservation);
 91	        return reservation;
 92	    }
 93	
 94	    public synchronized Reservation checkIn(long reservationId) {
 95	        Reservation reservation = find(reservationId);
 96	        if (reservation.status() != ReservationStatus.CONFIRMED) {
 97	            throw notAllowed(reservation, "check in");
 98	        }
 99	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
100	        store.update(reservation);
101	        return reservation;
102	    }
103	
104	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
105	    public synchronized DocumentReceipt checkOut(long reservationId) {
106	        Reservation reservation = find(reservationId);
107	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
108	            throw notAllowed(reservation, "check out");
109	        }
110	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
111	        store.update(reservation);
112	        return DocumentReceipt.of(reservation, roomOf(reservation));
113	    }
114	
115	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
116	    public DocumentReceipt receiptCopy(long reservationId) {
117	        Reservation reservation = find(reservationId);
118	        if (!reservation.isPaid()) {
119	            throw notAllowed(reservation, "issue a receipt for");
120	        }
121	        return DocumentReceipt.of(reservation, roomOf(reservation));
122	    }
123	
124	    private Room roomOf(Reservation reservation) {
125	        return rooms.find(reservation.roomNumber()).orElseThrow();
126	    }
127	
128	    private String generateDocumentText(Reservation reservation, Room room) {
129	        return switch (reservation.guest().type()) {
130	            case INDIVIDUAL -> new ReservationReceipt(reservation, room).text();
131	            case COMPANY -> new InvoiceReceipt(reservation, room).text();
132	            case FOREIGN -> new BookingReceipt(reservation, room).text();
133	        };
134	    }
135	
136	    private static String confirmationEmailBody(Reservation reservation, String documentText) {
137	        return "Olá, " + reservation.guest().name() + "!\n\n"
138	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
139	                + documentText + "\n"
140	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
141	                + "Até breve!\n";
142	    }
143	
144	    private static HotelException notAllowed(Reservation reservation, String operation) {
145	        return new HotelException(
146	                ErrorCode.OPERATION_NOT_ALLOWED,
147	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
148	    }
149	}
  1	package hotel.documents;
  2	
  3	import hotel.reservations.Reservation;
  4	import hotel.rooms.Room;
  5	import hotel.rooms.RoomType;
  6	import java.math.BigDecimal;
  7	import java.time.LocalDate;
  8	
  9	/** The receipt the guest gets when the reservation is confirmed, at check-out, and on request. */
 10	public record ReservationReceipt(
 11	        String title,
 12	        long reservationId,
 13	        String guestName,
 14	        String guestCpf,
 15	        int roomNumber,
 16	        RoomType roomType,
 17	        LocalDate checkIn,
 18	        LocalDate checkOut,
 19	        int nights,
 20	        BigDecimal subtotal,
 21	        BigDecimal discount,
 22	        BigDecimal total) {
 23	
 24	    public ReservationReceipt(Reservation reservation, Room room) {
 25	        this(
 26	                "Comprovante de reserva",
 27	                reservation.id(),
 28	                reservation.guest().name(),
 29	                reservation.guest().cpf(),
 30	                room.number(),
 31	                room.type(),
 32	                reservation.checkIn(),
 33	                reservation.checkOut(),
 34	                reservation.price().nights(),
 35	                reservation.price().subtotal(),
 36	                reservation.price().discount(),
 37	                reservation.price().total());
 38	    }
 39	
 40	    public String text() {
 41	        StringBuilder text = new StringBuilder();
 42	        text.append(title).append(" nº ").append(reservationId).append('\n');
 43	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
 44	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
 45	        text.append("Entrada: ").append(TextFormat.date(checkIn))
 46	                .append(" | Saída: ").append(TextFormat.date(checkOut))
 47	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
 48	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
 49	        if (discount.signum() > 0) {
 50	            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
 51	        }
 52	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
 53	        return text.toString();
 54	    }
 55	}
  1	package hotel.reservations;
  2	
  3	public record Guest(
  4	        String name,
  5	        String email,
  6	        String cpf,
  7	        String companyCnpj,
  8	        String companyName,
  9	        String passport,
 10	        String country) {
 11	
 12	    public Guest(String name, String email, String cpf) {
 13	        this(name, email, cpf, null, null, null, null);
 14	    }
 15	
 16	    public Guest(String name, String email, String companyCnpj, String companyName) {
 17	        this(name, email, null, companyCnpj, companyName, null, null);
 18	    }
 19	
 20	    public static Guest withPassport(String name, String email, String passport, String country) {
 21	        return new Guest(name, email, null, null, null, passport, country);
 22	    }
 23	
 24	    public GuestType type() {
 25	        if (cpf != null) {
 26	            return GuestType.INDIVIDUAL;
 27	        } else if (companyCnpj != null) {
 28	            return GuestType.COMPANY;
 29	        } else {
 30	            return GuestType.FOREIGN;
 31	        }
 32	    }
 33	}

